#pragma once

#include <string_view>

inline constexpr std::string_view kPortalPage = R"HTML(<!doctype html>
<html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Mouse Bridge</title><style>
:root{color-scheme:dark;font-family:system-ui,sans-serif;background:#111;color:#eee}body{margin:0;padding:20px;max-width:680px;margin:auto}h1{font-size:1.35rem;margin:0 0 4px}h2{font-size:1rem;margin:24px 0 10px;color:#bbb}.sub,#status{color:#999;font-size:.9rem}.card{display:flex;align-items:center;gap:12px;padding:12px 0;border-bottom:1px solid #292929}.info{min-width:0;flex:1}.name{font-weight:650;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.meta{font:12px ui-monospace,monospace;color:#888;margin-top:3px}.dot{width:9px;height:9px;border-radius:50%;background:#3ecf70;display:inline-block;margin-right:7px}button{border:0;border-radius:8px;padding:9px 12px;background:#2b66e3;color:white;font-weight:650}button.alt{background:#303030}button.danger{background:#6e3030}button:disabled{opacity:.45}.actions{display:flex;gap:7px;flex-wrap:wrap;justify-content:flex-end}.empty{padding:14px 0;color:#777}.saved{color:#78a7ff}#close{float:right;margin-top:-34px}@media(max-width:500px){body{padding:16px}.card{align-items:flex-start;flex-direction:column}.actions{width:100%}.actions button{flex:1}}
</style></head><body><h1>Mouse Bridge</h1><div class="sub">Chọn chuột BLE cho ESP32-S3</div><button id="close" class="alt">Đóng cấu hình</button><div id="status">Đang tải…</div><h2>Đã kết nối trước đây</h2><div id="saved"></div><h2>Thiết bị ở gần</h2><div id="nearby"></div>
<script>
const $=id=>document.getElementById(id);let busy=false;
const labels={idle:'Sẵn sàng',scanning:'Đang tìm thiết bị đã chọn…',portal:'Đang quét BLE…',switching:'Đang chuyển thiết bị…',connecting:'Đang kết nối…',connected:'Đã kết nối',success:'Kết nối thành công, Wi‑Fi sắp tắt',failed:'Kết nối thất bại'};
function button(text,cls,fn,disabled=false){const b=document.createElement('button');b.textContent=text;b.className=cls||'';b.disabled=disabled;b.onclick=fn;return b}
function form(d){return 'address='+encodeURIComponent(d.address)+'&type='+d.type}
async function post(path,body=''){busy=true;try{await fetch(path,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body})}finally{busy=false;setTimeout(load,150)}}
function info(d,connected=false){const box=document.createElement('div');box.className='info';const n=document.createElement('div');n.className='name';if(connected){const dot=document.createElement('span');dot.className='dot';n.append(dot)}n.append(document.createTextNode(d.name));const m=document.createElement('div');m.className='meta';m.textContent=d.address+(d.rssi===undefined?'':' · '+d.rssi+' dBm');box.append(n,m);return box}
function renderSaved(items){const root=$('saved');root.replaceChildren();if(!items.length){root.innerHTML='<div class="empty">Chưa có thiết bị</div>';return}items.forEach(d=>{const row=document.createElement('div');row.className='card';row.append(info(d,d.connected));const a=document.createElement('div');a.className='actions';if(d.connected)a.append(button('Ngắt kết nối','alt',()=>post('/api/disconnect'),busy));else a.append(button('Kết nối','',()=>post('/api/connect',form(d)),busy));a.append(button('Xóa','danger',()=>{if(confirm('Xóa thiết bị này và bond đã lưu?'))post('/api/forget',form(d))},busy));row.append(a);root.append(row)})}
function renderNearby(items){const root=$('nearby');root.replaceChildren();if(!items.length){root.innerHTML='<div class="empty">Đang quét, chưa thấy thiết bị…</div>';return}items.forEach(d=>{const row=document.createElement('div');row.className='card';const box=info(d);if(d.saved){const mark=document.createElement('div');mark.className='meta saved';mark.textContent='Đã lưu';box.append(mark)}row.append(box);const a=document.createElement('div');a.className='actions';a.append(button(d.busy?'Đang kết nối…':'Kết nối','',()=>post('/api/connect',form(d)),busy||d.busy));row.append(a);root.append(row)})}
async function load(){try{const r=await fetch('/api/state',{cache:'no-store'});const s=await r.json();$('status').textContent=labels[s.phase]||s.phase;renderSaved(s.saved);renderNearby(s.nearby)}catch(e){$('status').textContent='Mất kết nối với portal'}setTimeout(load,1000)}
$('close').onclick=()=>post('/api/close');load();
</script></body></html>)HTML";
